import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.DTdEDYjJ.js";const u=JSON.parse('{"title":"浏览器 Computer Use","description":"","frontmatter":{},"headers":[],"relativePath":"guide/computer-use.md","filePath":"guide/computer-use.md"}'),r={name:"guide/computer-use.md"};function s(i,t,n,p,c,l){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="浏览器-computer-use" tabindex="-1">浏览器 Computer Use <a class="header-anchor" href="#浏览器-computer-use" aria-label="Permalink to &quot;浏览器 Computer Use&quot;">​</a></h1><p>OpenBot提供每个 Bot 独立的 <strong>Chromium 浏览器工作屏幕</strong>，支持本机 Mac 与显式连接的自建 Linux Node。当前没有完整操作系统桌面、任意桌面应用或虚拟机控制接口。</p><h2 id="开始一项浏览器任务" tabindex="-1">开始一项浏览器任务 <a class="header-anchor" href="#开始一项浏览器任务" aria-label="Permalink to &quot;开始一项浏览器任务&quot;">​</a></h2><ol><li>为目标 Bot 保存模型连接、模型和 Harness；确认模型能处理这项任务需要的图像与工具调用。</li><li>在该 Bot 设置中显式开启工具。普通 API 对话不因模型支持工具而自动获得屏幕权限。</li><li>明确要访问的网页与目标，先选无副作用的阅读任务。</li><li>打开工作屏幕，核对 Bot、执行机器和页面。远端任务需先保存节点连接并连接执行会话。</li><li>出现修改操作审批时核对参数；完成后核查实际页面与任务结果。</li></ol><p>可从这样的小任务开始：</p><blockquote><p>在你的浏览器中打开 <a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a>，读取页面标题和第一段文字，不修改页面。</p></blockquote><p>向执行 Bot 派发浏览器任务时必须明确选择浏览器模式；省略模式始终是文字任务，见<a href="/openbot/guide/jarvis.html">贾维斯模式</a>。</p><h2 id="当前工具范围" tabindex="-1">当前工具范围 <a class="header-anchor" href="#当前工具范围" aria-label="Permalink to &quot;当前工具范围&quot;">​</a></h2><p>普通 API 执行 Bot 只拥有本 Bot 屏幕的六项工具：</p><table tabindex="0"><thead><tr><th>工具</th><th>用途</th><th>关键边界</th></tr></thead><tbody><tr><td><code>screen_open</code></td><td>打开网页</td><td>限 HTTP/HTTPS；不是任意协议启动器</td></tr><tr><td><code>screen_capture</code></td><td>取得画面</td><td>有效新观察才允许继续 Agent 输入</td></tr><tr><td><code>screen_click</code></td><td>按截图坐标点击</td><td>双击须明确要求，计为两次点击</td></tr><tr><td><code>screen_type</code></td><td>输入普通文字</td><td>不用于密码或验证码</td></tr><tr><td><code>screen_key</code></td><td>发送允许的按键</td><td>只接受工具声明的按键</td></tr><tr><td><code>screen_scroll</code></td><td>上下滚动</td><td>动作后取得新观察再决策</td></tr></tbody></table><p>浏览器权限请求、弹窗、下载及非 HTTP 导航默认拒绝。浏览器工具不包含任意模型 JavaScript、Shell 或完整桌面控制；普通执行 Bot 也没有文件管理、组织管理和再次派单工具。</p><h2 id="审批、观察与完成" tabindex="-1">审批、观察与完成 <a class="header-anchor" href="#审批、观察与完成" aria-label="Permalink to &quot;审批、观察与完成&quot;">​</a></h2><p>一次授权只批准对应调用。OpenBot 在输入真正发送前再次检查权限、控制权和动作预算；同一模型回复对同一屏幕最多执行一个有效输入，后续输入必须等待新观察。</p><p>动作发出后，OpenBot 不用动作前缓存补成成功截图。若新画面失败，任务保留“动作已发出、需要观察”的证据，后续输入会被阻止；先查看新画面，不直接重复点击。</p><p>人工预览不建立 Agent 的观察许可。两个新画面看起来相同也不代表业务失败，例如页面已经无法继续滚动；像素变化也不证明服务端业务已完成。</p><table tabindex="0"><thead><tr><th>完成核查</th><th>含义</th></tr></thead><tbody><tr><td><code>confirmed</code></td><td>宿主只读检查匹配本次声明的页面条件</td></tr><tr><td><code>unmet</code></td><td>已检查，但页面条件尚未满足</td></tr><tr><td><code>unknown</code></td><td>证据不足或存在未知副作用，需核查</td></tr><tr><td><code>not-required</code></td><td>没有浏览器副作用，也未声明页面条件</td></tr></tbody></table><p>模型自称完成不能把未知结果变成成功。页面条件只证明该次页面检查匹配，不能推定支付、服务端事务或任意异步流程已经完成。</p><h2 id="人工接管与交还" tabindex="-1">人工接管与交还 <a class="header-anchor" href="#人工接管与交还" aria-label="Permalink to &quot;人工接管与交还&quot;">​</a></h2><p>遇到登录、验证码、错误页面或需要自己操作时，点击“人工接管”。接管会使旧 Agent 观察和待执行输入失效；你可以在预览里操作目标屏幕。</p><p>核对页面后显式“交还”。交还后 Agent 必须重新观察，再决定下一步，旧输入不会自动回放。不同 Bot 屏幕独立，一个 Bot 被接管不等于所有 Bot 都停止。</p><p>停止与取消不能撤销已发生的外部操作。若动作可能已经发出，先检查页面和记录，再决定是否重新交办。</p><h2 id="次数与结果不确定" tabindex="-1">次数与结果不确定 <a class="header-anchor" href="#次数与结果不确定" aria-label="Permalink to &quot;次数与结果不确定&quot;">​</a></h2><p>明确说明次数和完成条件，例如“点击按钮一次且不要重复，确认画面显示目标文字后结束”。支持范围内的次数会转换为持久动作预算；双击按两个点击单位计数。</p><p>已发出或结果未知的动作继续占用额度，不因超时、截图失败、取消或重启自动返还。额度不足或条件无法安全分配时会拒绝继续，不能用重复派单绕过。</p><p>当前有次数规则或页面完成条件的父任务不能跨机器委派。独立远端任务按其自己的已保存指令建立约束，完整的跨主机额度移交尚未实现。</p><h2 id="node-断线与恢复" tabindex="-1">Node 断线与恢复 <a class="header-anchor" href="#node-断线与恢复" aria-label="Permalink to &quot;Node 断线与恢复&quot;">​</a></h2><p>一个 Node 同时只允许一个控制客户端。租约到期或连接中断后，旧审批和旧屏幕输入失效，执行在模型或工具边界暂停。</p><p>恢复顺序是：重建 SSH 隧道 → 连接执行会话 → 核对新画面 → 显式交还。重新连接不自动恢复旧控制权，也不重放离线输入。</p><p>Node 重启将未完成任务标为 <code>interrupted</code>，不自动重派。提交回执丢失也不会换一个请求 ID 自动重试；先核查现有任务。</p><h2 id="开发者本地验证" tabindex="-1">开发者本地验证 <a class="header-anchor" href="#开发者本地验证" aria-label="Permalink to &quot;开发者本地验证&quot;">​</a></h2><p>从源码根目录运行受控套件，使用独立临时数据、本地页面与模型替身，不消耗真实模型额度：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:computer-use</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:observation</span></span></code></pre></div><p>这些命令需要本机 Electron 运行环境；未指定 <code>OPENBOT_E2E_APP</code> 时验证源码，不能替代最终包。实现入口可查仓库 <code>src/screen.js</code>、<code>src/tools.js</code>、<code>src/action-ledger.js</code> 与 <code>node/execution.js</code>。</p><p>下一步见<a href="/openbot/deployment/self-host.html">自建 Linux Node</a>、<a href="/openbot/reference/node-api.html">节点 API</a>与<a href="/openbot/concepts/architecture.html">架构</a>。</p>`,34)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
